CREATE TABLE migration_000014_option_snapshot AS
SELECT o.id,o.option_text
FROM chat_options o
JOIN chat_steps st ON st.id=o.step_id
JOIN chats c ON c.id=st.chat_id
WHERE c.product_context->>'content_version'='issue-103-complete';
ALTER TABLE migration_000014_option_snapshot ADD PRIMARY KEY(id);

CREATE TABLE migration_000014_phase_replies (
    topic_slug VARCHAR PRIMARY KEY,
    opening_safe TEXT NOT NULL,
    opening_cautious TEXT NOT NULL,
    opening_unsafe TEXT NOT NULL,
    request_cautious TEXT NOT NULL,
    request_unsafe TEXT NOT NULL,
    pressure_cautious TEXT NOT NULL,
    pressure_unsafe TEXT NOT NULL
);

INSERT INTO migration_000014_phase_replies VALUES
('buyer-phishing-links','Да, доставка подходит. Оформите заказ через Avito, я проверю его в приложении.','Спасибо. Сначала уточню состояние телефона и условия доставки здесь.','Отлично, пришлите ссылку для быстрой оплаты.','Сначала проверю, есть ли такой заказ в приложении, а вашу форму открывать не буду.','Форма выглядит нормально, сейчас открою её и оплачу заказ.','Я не буду торопиться: сначала проверю заказ и условия доставки в приложении.','Ладно, оплачу сейчас, чтобы товар не достался другому покупателю.'),
('buyer-prepayment','Спасибо. Бронировать переводом не буду, но готов оформить покупку через Avito.','Уточните состояние и комплектацию, потом решу насчёт покупки.','Придержите её, я готов перевести деньги за бронь.','Реквизиты получил, но сначала проверю продавца и условия сделки.','Хорошо, сейчас переведу 3 000 ₽ за бронь на эту карту.','Мне нужно время на проверку; без неё деньги переводить не буду.','Ладно, перевожу сейчас, пока другой покупатель не забрал товар.'),
('buyer-fake-delivery','Хорошо, оформите доставку внутри Avito, я проверю заказ в приложении.','Сначала уточню состояние и комплект пылесоса, затем обсудим доставку.','Отлично, присылайте любые данные для оформления курьера.','Сначала уточню в поддержке, существует ли такая страховка.','Открою вашу форму и оплачу страховку курьера.','Пусть курьер подождёт, я сначала проверю условия доставки.','Хорошо, оплачу сейчас, чтобы заказ не отменился.'),
('buyer-off-platform','Да, пришлите видео сюда, в чат Avito.','Сначала расскажите о состоянии камеры и комплекте здесь.','Давайте перейдём в Telegram, там удобнее посмотреть видео.','Видео посмотрю только здесь; в Telegram и по QR переходить не буду.','Хорошо, напишу вам в Telegram и открою QR.','Скидка подождёт: сначала проверю заказ внутри Avito.','Перейду по QR сейчас, чтобы получить скидку.'),
('buyer-sms-codes','Я сам проверю заказы в приложении; коды для этого никому не сообщаю.','Уточните, что именно случилось с заказами, а я проверю их самостоятельно.','Хорошо, помогите отменить лишний заказ, я сообщу нужный код.','Сначала проверю в приложении, есть ли лишний заказ; код называть не буду.','Хорошо, продиктую код, чтобы вы отменили лишний заказ.','Я не тороплюсь и сам проверю списания в приложении.','Ладно, сообщу код сейчас, чтобы деньги не списались повторно.'),
('buyer-too-good-offer','Предложение интересно, но оформлять буду только штатно после проверки.','Расскажите о состоянии и причине такой цены, я всё проверю.','Отличная цена, готов сразу внести деньги, чтобы товар остался за мной.','Сначала проверю заказ и продавца, а во внешней форме платить не буду.','Хорошо, внесу 5 000 ₽ через вашу форму для курьера.','Я не буду решать за три минуты; сначала всё проверю.','Ладно, заплачу сейчас, пока ноутбук не купил кто-то другой.'),
('seller-fake-payment','Хорошо. Товар передам после того, как сам увижу оплату в банке или заказе.','Уточните способ получения, а оплату я проверю самостоятельно.','Отлично, после вашего чека сразу передам телефон курьеру.','Сначала проверю поступление денег в банке; форму открывать не буду.','Хорошо, открою форму и введу данные карты для получения денег.','Курьер подождёт: товар отдам только после подтверждения оплаты.','Ладно, подтвержу карту сейчас, чтобы с вас не списали комиссию.'),
('seller-fake-delivery','Хорошо, я проверю оформленный заказ внутри Avito перед передачей.','Уточните время приезда курьера, а заказ я пока проверю.','Отлично, передам кофемашину курьеру без проверки заказа.','Сначала проверю в заказе, должна ли вообще оплачиваться такая страховка.','Хорошо, оплачу страховку по вашей форме.','Курьер подождёт, пока я проверю правила доставки в приложении.','Ладно, переведу деньги сейчас, чтобы курьер не уехал.'),
('seller-external-links','Хорошо, сначала проверю заказ и оплату в разделе продаж Avito.','Уточните время доставки, а я пока проверю статус заказа.','Отлично, пришлите подтверждение оплаты или ссылку на заказ.','Сначала проверю заказ в разделе продаж; вашу страницу открывать не буду.','Хорошо, открою страницу и введу реквизиты карты.','Оплата подождёт, пока я самостоятельно проверю заказ в приложении.','Ладно, активирую оплату сейчас, пока она не зависла.'),
('seller-confirmation-codes','Я сам проверю статус профиля в приложении; коды никому не сообщаю.','Уточните, что именно видите, а профиль я проверю самостоятельно.','Хорошо, помогите подтвердить профиль, я сообщу нужный код.','Сначала проверю профиль и заказы самостоятельно; код никому не назову.','Хорошо, перешлю код вашему специалисту.','Угрозу блокировки я проверю в официальной поддержке, а код не сообщу.','Ладно, отправлю код сейчас, чтобы заказ не отменился.'),
('seller-off-platform','Опишите проблему здесь, в чате; номер телефона передавать не буду.','Попробуйте открыть видео ещё раз, а детали обсудим здесь.','Давайте перейдём в WhatsApp, там видео точно откроется.','Опишите ошибку здесь; номер телефона и WhatsApp для этого не нужны.','Хорошо, напишу вам в WhatsApp и свяжусь со специалистом.','Поддержка подождёт: сначала сам открою её внутри приложения.','Ладно, перейду в WhatsApp сейчас, пока обращение не закрыли.'),
('seller-pressure','Хорошо, товар отдам только после проверки денег в своём банке.','Уточните время приезда курьера, а я пока проверю перевод.','Отлично, раз перевод отправлен, передам камеру курьеру.','Сначала проверю перевод в своём банке; по скриншоту камеру не передам.','Хорошо, передам камеру курьеру по вашему скриншоту.','Курьер подождёт, пока я самостоятельно проверю оплату и заказ.','Ладно, отдам камеру сейчас, чтобы с вас не списали деньги.');

WITH base AS (
    SELECT t.slug,
        MAX(o.option_text) FILTER (WHERE l.level_number=1 AND st.step_number=2 AND o.sort_order=1) request_safe,
        MAX(o.option_text) FILTER (WHERE l.level_number=1 AND st.step_number=3 AND o.sort_order=1) pressure_safe
    FROM chat_options o
    JOIN chat_steps st ON st.id=o.step_id
    JOIN chats c ON c.id=st.chat_id
    JOIN topics t ON t.id=c.topic_id
    JOIN levels l ON l.id=c.level_id
    WHERE c.content_status='published' AND c.archived_at IS NULL
      AND c.product_context->>'content_version'='issue-103-complete'
    GROUP BY t.slug
), replies AS (
    SELECT b.slug,
        ARRAY[p.opening_safe,p.opening_cautious,p.opening_unsafe] opening,
        ARRAY[b.request_safe,p.request_cautious,p.request_unsafe] request,
        ARRAY[b.pressure_safe,p.pressure_cautious,p.pressure_unsafe] pressure
    FROM base b JOIN migration_000014_phase_replies p ON p.topic_slug=b.slug
)
UPDATE chat_options o SET option_text=CASE l.level_number
    WHEN 1 THEN CASE st.step_number
        WHEN 1 THEN r.opening[o.sort_order]
        WHEN 2 THEN r.request[o.sort_order]
        ELSE r.pressure[o.sort_order] END
    WHEN 2 THEN 'Точно: '||CASE st.step_number
        WHEN 1 THEN r.opening[o.sort_order]
        ELSE r.request[o.sort_order] END
    ELSE 'Сразу скажу: '||r.opening[o.sort_order] END
FROM chat_steps st
JOIN chats c ON c.id=st.chat_id
JOIN topics t ON t.id=c.topic_id
JOIN levels l ON l.id=c.level_id
JOIN replies r ON r.slug=t.slug
WHERE o.step_id=st.id
  AND c.content_status='published' AND c.archived_at IS NULL
  AND c.product_context->>'content_version'='issue-103-complete'
  AND (l.level_number IN(1,2) OR (l.level_number=3 AND st.step_number=1));

DROP TABLE migration_000014_phase_replies;
